21	/** `repr()` of a `str`: single quotes unless that forces extra escaping. */
22	export function reprString(text) {
23	  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
24	  let body = '';
25	  for (const character of text) {
26	    if (character === quote) {
27	      body += `\\${character}`;
28	    } else if (SIMPLE_ESCAPES.has(character)) {
29	      body += SIMPLE_ESCAPES.get(character);
30	    } else if (isPrintable(character)) {
31	      body += character;
32	    } else {
33	      body += escapeUnprintable(character);
34	    }
35	  }
36	  return `${quote}${body}${quote}`;
