import { readFileSync } from 'node:fs';

/** PEP 383 surrogateescape UTF-8 decode of one raw argv element. */
function decodeSurrogateEscape(buf) {
  let out = '';
  let i = 0;
  while (i < buf.length) {
    const b = buf[i];
    let len = 0;
    let cp = 0;
    if (b < 0x80) { out += String.fromCharCode(b); i += 1; continue; }
    else if (b >= 0xc2 && b <= 0xdf) { len = 2; cp = b & 0x1f; }
    else if (b >= 0xe0 && b <= 0xef) { len = 3; cp = b & 0x0f; }
    else if (b >= 0xf0 && b <= 0xf4) { len = 4; cp = b & 0x07; }
    else { out += String.fromCharCode(0xdc00 + b); i += 1; continue; }
    if (i + len > buf.length) { out += String.fromCharCode(0xdc00 + b); i += 1; continue; }
    let ok = true;
    for (let k = 1; k < len; k++) {
      const c = buf[i + k];
      if ((c & 0xc0) !== 0x80) { ok = false; break; }
      cp = (cp << 6) | (c & 0x3f);
    }
    if (!ok) { out += String.fromCharCode(0xdc00 + b); i += 1; continue; }
    // reject overlongs, surrogates, out-of-range
    if ((len === 3 && cp < 0x800) || (len === 4 && cp < 0x10000) ||
        (cp >= 0xd800 && cp <= 0xdfff) || cp > 0x10ffff) {
      out += String.fromCharCode(0xdc00 + b); i += 1; continue;
    }
    out += String.fromCodePoint(cp);
    i += len;
  }
  return out;
}

/** argv after the script, decoded with surrogateescape from the real bytes. */
export function rawArgs() {
  const wanted = process.argv.length - 2;
  if (wanted <= 0) return [];
  let parts;
  try {
    const raw = readFileSync('/proc/self/cmdline');
    parts = [];
    let start = 0;
    for (let i = 0; i < raw.length; i++) {
      if (raw[i] === 0) { parts.push(raw.subarray(start, i)); start = i + 1; }
    }
    if (start < raw.length) parts.push(raw.subarray(start));
  } catch {
    return process.argv.slice(2);
  }
  if (parts.length < wanted) return process.argv.slice(2);
  return parts.slice(parts.length - wanted).map(decodeSurrogateEscape);
}
